    const centerY = this.height / 2;
    const distanceX = Math.abs(centerX - this.horizontal_center);
    const distanceY = Math.abs(centerY - this.vertical_center);
    return Math.sqrt(distanceX * distanceX + distanceY * distanceY);
}

